using ConjuntoInteligente.PbBridge.Contracts; using ConjuntoInteligente.PbBridge.Contracts.Dtos; using ConjuntoInteligente.PbBridge.Services; using Microsoft.AspNetCore.Mvc;
namespace ConjuntoInteligente.PbBridge.Controllers;
[Route("pb/v1/orders")] public sealed class PbOrdersController:PbBaseController{private readonly ICoreClient _core;private readonly IPbMapper _mapper;public PbOrdersController(ICoreClient core,IPbMapper mapper){_core=core;_mapper=mapper;}
 [HttpPost("list")] public async Task<IActionResult> ListPost([FromBody]PbOrderListRequest req,CancellationToken ct)=>await ListInternal(req,ct);
 [HttpGet("list")] public async Task<IActionResult> ListGet([FromQuery]string? estado,[FromQuery]string? categoria,[FromQuery]string? busqueda,[FromQuery]int pagina=1,[FromQuery]int porPagina=50,CancellationToken ct=default)=>await ListInternal(new PbOrderListRequest{Estado=estado,Categoria=categoria,Busqueda=busqueda,Pagina=pagina,PorPagina=porPagina},ct);
 [HttpGet("{id}")] public async Task<IActionResult> Get(string id,CancellationToken ct){var o=await _core.GetAsync<CoreOrder>($"api/v1/maintenance/orders/{Uri.EscapeDataString(id)}",ct);if(o is null)return PbFail(PbErrorCodes.NotFound,"Orden no encontrada.",404);return PbOk(_mapper.ToPb(o));}
 [HttpPost] public async Task<IActionResult> Create([FromBody]PbOrderCreateRequest request,CancellationToken ct){var result=await _core.PostAsync<CoreMaintenanceMutation>("api/v1/maintenance/orders",request,ct);return result is null?PbFail(PbErrorCodes.CoreError,"El core no devolvió el resultado de creación.",502):StatusCode(201,PbResponse<CoreMaintenanceMutation>.Success(result));}
 [HttpPatch("{id}")] public async Task<IActionResult> Update(string id,[FromBody]PbOrderUpdateRequest request,CancellationToken ct){var result=await _core.PatchAsync<CoreMaintenanceMutation>($"api/v1/maintenance/orders/{Uri.EscapeDataString(id)}",request,ct);return result is null?PbFail(PbErrorCodes.NotFound,"Orden no encontrada.",404):PbOk(result);}
 [HttpPost("{id}/approve")] public async Task<IActionResult> Approve(string id,[FromBody]PbApprovalRequest request,CancellationToken ct){var result=await _core.PostAsync<CoreMaintenanceMutation>($"api/v1/maintenance/orders/{Uri.EscapeDataString(id)}/approve",request,ct);return result is null?PbFail(PbErrorCodes.NotFound,"Orden no encontrada.",404):PbOk(result);}
 [HttpPatch("{id}/status")] public async Task<IActionResult> SetStatus(string id,[FromBody]PbOrderStatusRequest request,CancellationToken ct){var result=await _core.PatchAsync<CoreMaintenanceMutation>($"api/v1/maintenance/orders/{Uri.EscapeDataString(id)}/status",request,ct);return result is null?PbFail(PbErrorCodes.NotFound,"Orden no encontrada.",404):PbOk(result);}
 private async Task<IActionResult> ListInternal(PbOrderListRequest req,CancellationToken ct){if(req.Pagina<1||req.PorPagina is <1 or >200)return PbFail(PbErrorCodes.ValidationError,"pagina debe ser positivo y porPagina debe estar entre 1 y 200.");var qs=new List<string>{$"page={req.Pagina}",$"page_size={req.PorPagina}"};if(!string.IsNullOrWhiteSpace(req.Estado))qs.Add($"status={Uri.EscapeDataString(req.Estado!)}");if(!string.IsNullOrWhiteSpace(req.Categoria))qs.Add($"category={Uri.EscapeDataString(req.Categoria!)}");if(!string.IsNullOrWhiteSpace(req.Busqueda))qs.Add($"q={Uri.EscapeDataString(req.Busqueda!)}");if(!string.IsNullOrWhiteSpace(req.Desde))qs.Add($"from={Uri.EscapeDataString(req.Desde!)}");if(!string.IsNullOrWhiteSpace(req.Hasta))qs.Add($"to={Uri.EscapeDataString(req.Hasta!)}");var page=await _core.GetAsync<CoreOrderPage>($"api/v1/maintenance/orders?{string.Join('&',qs)}",ct);if(page is null)return PbOk(new PbOrderListResponse{Items=[],Total=0,Pagina=req.Pagina,PorPagina=req.PorPagina});return PbOk(new PbOrderListResponse{Items=_mapper.ToPb(page.Items),Total=page.Total,Pagina=req.Pagina,PorPagina=req.PorPagina});}}
public sealed record CoreOrderPage(IReadOnlyList<CoreOrder> Items,int Total);
